1	use anyhow::Result;
2	use std::path::Path;
3	
4	pub fn hash_content(content: &[u8]) -> String {
5	    blake3::hash(content).to_hex().to_string()
6	}
7	
8	pub fn hash_file(path: &Path) -> Result<String> {
9	    let content = std::fs::read(path)?;
10	    Ok(hash_content(&content))
11	}
12	
13	pub fn hash_diff(old: &str, new: &str) -> String {
14	    let combined = format!("{}\x00{}", old, new);
15	    hash_content(combined.as_bytes())
16	}
