84	pub fn keys_dir() -> PathBuf {
85	    dirs::data_dir()
86	        .unwrap_or_else(|| {
87	            dirs::home_dir()
88	                .map(|h| h.join(".local/share"))
89	                .unwrap_or_else(|| PathBuf::from("/tmp"))
90	        })
91	        .join("codeflow")
92	        .join("keys")
93	}
