95	pub fn load_or_generate() -> Result<KeyPair> {
96	    let dir = keys_dir();
97	    let key_path = dir.join("signing.key");
98	    if key_path.exists() {
99	        KeyPair::load(&key_path)
100	    } else {
101	        let kp = KeyPair::generate();
102	        kp.save(&key_path)?;
103	        Ok(kp)
104	    }
105	}
