107	mod hex {
108	    pub fn encode(bytes: &[u8]) -> String {
109	        bytes.iter().map(|b| format!("{:02x}", b)).collect()
110	    }
111	
112	    pub fn decode(s: &str) -> Result<Vec<u8>, String> {
113	        if s.len() % 2 != 0 {
114	            return Err("odd length".to_string());
115	        }
116	        (0..s.len())
117	            .step_by(2)
118	            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
119	            .collect()
120	    }
121	}
