61	impl ProvenanceStore {
62	    pub fn open(db_path: &Path) -> Result<Self> {
63	        let conn = Connection::open(db_path)?;
64	        conn.execute_batch(
65	            "PRAGMA journal_mode=WAL;
66	             PRAGMA synchronous=NORMAL;
67	             PRAGMA busy_timeout=5000;",
68	        )?;
69	        conn.execute_batch(
70	            "CREATE TABLE IF NOT EXISTS provenance_records (
71	                id INTEGER PRIMARY KEY AUTOINCREMENT,
72	                session_id TEXT NOT NULL,
73	                timestamp_ms INTEGER NOT NULL,
74	                file_path TEXT NOT NULL,
75	                code_hash TEXT NOT NULL,
76	                model_id TEXT NOT NULL DEFAULT 'unknown',
77	                model_version TEXT NOT NULL DEFAULT '',
78	                contributor_type TEXT NOT NULL DEFAULT 'unknown',
79	                start_line INTEGER NOT NULL DEFAULT 0,
80	                end_line INTEGER NOT NULL DEFAULT 0,
81	                attestation_sig TEXT NOT NULL DEFAULT '',
82	                developer_id TEXT NOT NULL DEFAULT '',
83	                prompt_hash TEXT NOT NULL DEFAULT '',
84	                project_dir TEXT NOT NULL DEFAULT ''
85	            );
86	
87	            CREATE INDEX IF NOT EXISTS idx_provenance_file
88	                ON provenance_records(file_path);
89	            CREATE INDEX IF NOT EXISTS idx_provenance_session
90	                ON provenance_records(session_id);
91	            CREATE INDEX IF NOT EXISTS idx_provenance_timestamp
92	                ON provenance_records(timestamp_ms);
93	
94	            CREATE TABLE IF NOT EXISTS provenance_snapshots (
95	                id INTEGER PRIMARY KEY AUTOINCREMENT,
96	                session_id TEXT NOT NULL,
97	                file_path TEXT NOT NULL,
98	                content_hash TEXT NOT NULL,
99	                mtime_ns INTEGER NOT NULL,
100	                snapshot_time_ms INTEGER NOT NULL,
101	                UNIQUE(session_id, file_path)
102	            );",
103	        )?;
104	        Ok(Self { conn })
105	    }
