218	        self.conn.execute(
219	            "INSERT OR REPLACE INTO provenance_snapshots
220	             (session_id, file_path, content_hash, mtime_ns, snapshot_time_ms)
221	             VALUES (?1, ?2, ?3, ?4, ?5)",
