227	    pub fn get_snapshot(
228	        &self,
229	        session_id: &str,
230	        file_path: &str,
231	    ) -> Result<Option<(String, i64)>> {
232	        let result = self.conn.query_row(
233	            "SELECT content_hash, mtime_ns FROM provenance_snapshots
234	             WHERE session_id = ?1 AND file_path = ?2",
235	            params![session_id, file_path],
236	            |row| Ok((row.get(0)?, row.get(1)?)),
237	        );
238	        match result {
239	            Ok(v) => Ok(Some(v)),
240	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
241	            Err(e) => Err(e.into()),
242	        }
243	    }
244	
245	    pub fn get_all_snapshots(
246	        &self,
247	        session_id: &str,
248	    ) -> Result<HashMap<String, (String, i64)>> {
249	        let mut stmt = self.conn.prepare(
250	            "SELECT file_path, content_hash, mtime_ns FROM provenance_snapshots
251	             WHERE session_id = ?1",
252	        )?;
253	        let mut map = HashMap::new();
254	        let rows = stmt.query_map(params![session_id], |row| {
255	            Ok((
256	                row.get::<_, String>(0)?,
257	                row.get::<_, String>(1)?,
258	                row.get::<_, i64>(2)?,
259	            ))
260	        })?;
261	        for row in rows {
262	            let (path, hash, mtime) = row?;
263	            map.insert(path, (hash, mtime));
264	        }
265	        Ok(map)
266	    }
