268	    pub fn cleanup(&self, retention_days: i64) -> Result<u64> {
269	        let cutoff = now_ms() - (retention_days * 86_400_000);
270	        let changes = self.conn.execute(
271	            "DELETE FROM provenance_records WHERE timestamp_ms < ?1",
272	            params![cutoff],
273	        )?;
274	        Ok(changes as u64)
275	    }
