49	pub fn to_agent_trace(record: &ProvenanceRecord) -> TraceEntry {
50	    let ts = chrono::DateTime::from_timestamp_millis(record.timestamp_ms)
51	        .map(|dt| dt.to_rfc3339())
52	        .unwrap_or_else(|| record.timestamp_ms.to_string());
53	
54	    TraceEntry {
55	        timestamp: ts,
56	        file_path: record.file_path.clone(),
57	        code_hash: record.code_hash.clone(),
58	        contributor: TraceContributor {
59	            contributor_type: match record.contributor_type {
60	                ContributorType::Human => "human".to_string(),
61	                ContributorType::Ai => "ai".to_string(),
62	                ContributorType::Mixed => "mixed".to_string(),
63	                ContributorType::Unknown => "unknown".to_string(),
64	            },
65	            model_id: record.model_id.clone(),
66	            model_version: record.model_version.clone(),
67	            developer_id: record.developer_id.clone(),
68	        },
69	        lines: TraceLineRange {
70	            start: record.start_line,
71	            end: record.end_line,
72	        },
73	        attestation: TraceAttestation {
74	            algorithm: "ed25519".to_string(),
75	            signature: record.attestation_sig.clone(),
76	        },
77	        session_id: record.session_id.clone(),
78	    }
79	}
80	
81	pub fn export_agent_trace(records: &[ProvenanceRecord]) -> String {
82	    let trace = AgentTrace {
83	        version: "0.1.0".to_string(),
84	        generator: TraceGenerator {
85	            name: "codeflow".to_string(),
86	            version: env!("CARGO_PKG_VERSION").to_string(),
87	        },
88	        entries: records.iter().map(to_agent_trace).collect(),
89	    };
90	    serde_json::to_string_pretty(&trace).unwrap_or_else(|_| "{}".to_string())
91	}
