171	fn handle_blame(file: &str, json: bool, session: Option<&str>, trace: bool) -> anyhow::Result<()> {
172	    let db_path = paths::db_path();
173	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
174	
175	    let project_dir = std::env::current_dir().unwrap_or_default();
176	    let abs_path = if std::path::Path::new(file).is_absolute() {
177	        std::path::PathBuf::from(file)
178	    } else {
179	        project_dir.join(file)
180	    };
181	
182	    let rel_path = abs_path
183	        .strip_prefix(&project_dir)
184	        .map(|r| r.to_string_lossy().replace('\\', "/"))
185	        .unwrap_or_else(|_| file.to_string());
186	
187	    let mut records = store.query_by_file(&rel_path)?;
188	    if let Some(sid) = session {
189	        records.retain(|r| r.session_id == sid);
190	    }
191	
192	    if trace {
193	        println!("{}", codeflow_core::agent_trace::export_agent_trace(&records));
194	        return Ok(());
195	    }
196	
197	    if json {
198	        println!("{}", serde_json::to_string_pretty(&records)?);
199	        return Ok(());
200	    }
201	
202	    if records.is_empty() {
203	        println!("No provenance records for {}", rel_path);
204	        return Ok(());
205	    }
206	
207	    let file_content = std::fs::read_to_string(&abs_path).unwrap_or_default();
208	    let lines: Vec<&str> = file_content.lines().collect();
209	
210	    println!("Provenance: {} ({} records)\n", rel_path, records.len());
211	
212	    for rec in &records {
213	        let ts = chrono::DateTime::from_timestamp_millis(rec.timestamp_ms)
214	            .map(|dt| dt.format("%Y-%m-%d %H:%M").to_string())
215	            .unwrap_or_else(|| "?".to_string());
216	
217	        let ct_label = match rec.contributor_type {
218	            codeflow_core::provenance::ContributorType::Human => "\x1b[32mhuman\x1b[0m",
219	            codeflow_core::provenance::ContributorType::Ai => "\x1b[33mai\x1b[0m",
220	            codeflow_core::provenance::ContributorType::Mixed => "\x1b[36mmixed\x1b[0m",
221	            codeflow_core::provenance::ContributorType::Unknown => "\x1b[90munknown\x1b[0m",
222	        };
223	
224	        println!(
225	            "  {} | {} | {} | L{}-{} | {}",
226	            ts, ct_label, rec.model_id, rec.start_line, rec.end_line, &rec.code_hash[..12]
227	        );
228	    }
229	
230	    if !lines.is_empty() {
231	        println!("\nLine attribution:");
232	        for (i, line) in lines.iter().enumerate() {
233	            let line_num = (i + 1) as u32;
234	            let attr = records.iter().find(|r| {
235	                r.start_line <= line_num && r.end_line >= line_num
236	            });
237	            let prefix = match attr {
238	                Some(r) => match r.contributor_type {
239	                    codeflow_core::provenance::ContributorType::Ai => "\x1b[33m AI \x1b[0m",
240	                    codeflow_core::provenance::ContributorType::Human => "\x1b[32m HU \x1b[0m",
241	                    codeflow_core::provenance::ContributorType::Mixed => "\x1b[36m MX \x1b[0m",
242	                    codeflow_core::provenance::ContributorType::Unknown => "\x1b[90m ?? \x1b[0m",
243	                },
244	                None => "\x1b[90m -- \x1b[0m",
245	            };
246	            println!("{:>4} |{}| {}", line_num, prefix, line);
247	        }
248	    }
249	
250	    Ok(())
251	}
