253	fn handle_route(command: &str, tokens: u64, files: &[String]) -> anyhow::Result<()> {
254	    let cmd = command.to_string();
255	    if cmd.is_empty() {
256	        anyhow::bail!("no command provided");
257	    }
258	
259	    let file_refs: Vec<&str> = files.iter().map(|f| f.as_str()).collect();
260	    let extensions = codeflow_core::router::extensions_from_paths(&file_refs);
261	
262	    let input = codeflow_core::router::RoutingInput {
263	        command: cmd.clone(),
264	        context_tokens: tokens,
265	        file_extensions: extensions,
266	        session_event_count: 0,
267	    };
268	
269	    let decision = codeflow_core::router::classify(&input);
270	
271	    println!("Command:    {}", cmd);
272	    println!("Tokens:     {}", tokens);
273	    println!("Score:      {:.2}", decision.score);
274	    println!("Complexity: {:?}", decision.complexity);
275	    println!("Route to:   {} (${}/1M tokens)", decision.tier.name(), decision.tier.cost_per_million_tokens());
276	    println!("Savings:    {:.0}% vs Opus", decision.estimated_savings_pct);
277	    if !decision.reason.is_empty() {
278	        println!("Reason:     {}", decision.reason);
279	    }
280	
281	    Ok(())
282	}
283	
284	fn handle_cache(action: CacheAction) -> anyhow::Result<()> {
285	    let db_path = paths::db_path();
286	    match action {
287	        CacheAction::Clear => {
288	            if db_path.exists() {
289	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
290	                let removed = cache.clear()?;
291	                println!("Cleared {} cache entries.", removed);
292	            } else {
293	                println!("Cache is empty.");
294	            }
295	            Ok(())
296	        }
297	        CacheAction::Info => {
298	            if db_path.exists() {
