318	fn capture_provenance(
319	    session_id: &str,
320	    tool_name: &str,
321	    tool_input: &serde_json::Value,
322	) -> anyhow::Result<()> {
323	    let db_path = paths::db_path();
324	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
325	    let keypair = codeflow_core::attestation::load_or_generate()?;
326	    let project_dir = std::env::current_dir().unwrap_or_default();
327	
328	    // Step 1: diff against previous snapshots → record provenance for prior tool's changes
329	    let changes = codeflow_core::provenance::detect_changes(
330	        &project_dir,
331	        session_id,
332	        &store,
333	        &keypair,
334	    )?;
335	    for rec in &changes {
336	        store.record(rec)?;
337	        // Update snapshot to current state after recording
338	        if let Ok(hash) = codeflow_core::content_hash::hash_file(&project_dir.join(&rec.file_path)) {
339	            let mtime = codeflow_core::util::get_file_mtime_ns(
340	                project_dir.join(&rec.file_path).to_str().unwrap_or(""),
341	            )
342	            .unwrap_or(0);
343	            store.save_snapshot(session_id, &rec.file_path, &hash, mtime)?;
344	        }
345	    }
346	
347	    // Step 2: snapshot files targeted by the current tool for next comparison
348	    let files_to_snapshot = extract_target_files(tool_name, tool_input, &project_dir);
349	    if !files_to_snapshot.is_empty() {
350	        codeflow_core::provenance::snapshot_files(
351	            &project_dir,
352	            session_id,
353	            &store,
354	            &files_to_snapshot,
355	        )?;
356	    }
357	
358	    Ok(())
359	}
360	
361	fn extract_target_files(
362	    tool_name: &str,
363	    tool_input: &serde_json::Value,
364	    project_dir: &std::path::Path,
365	) -> Vec<String> {
366	    let mut files = Vec::new();
367	    match tool_name {
368	        "Edit" | "Write" | "MultiEdit" | "NotebookEdit" => {
369	            if let Some(fp) = tool_input.get("file_path").and_then(|v| v.as_str()) {
370	                if let Some(rel) = to_relative(fp, project_dir) {
371	                    files.push(rel);
372	                }
373	            }
374	        }
375	        "Bash" => {
376	            // Bash can modify files; we can't know which ones ahead of time.
377	            // Snapshot tracked files that git reports as modified after the command runs.
378	            // Since PreToolUse fires BEFORE execution, we can only snapshot what's
379	            // already tracked. The diff-on-next-PreToolUse pattern handles detection.
380	        }
381	        _ => {}
382	    }
383	    files
384	}
