393	fn handle_pre_tool_use() -> anyhow::Result<()> {
394	    let input = match read_stdin() {
395	        Ok(s) => s,
396	        Err(e) => {
397	            eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
398	            println!("{{}}");
399	            return Ok(());
400	        }
401	    };
402	
403	    let parsed: serde_json::Value = match serde_json::from_str(&input) {
404	        Ok(v) => v,
405	        Err(e) => {
406	            eprintln!(
407	                "[codeflow] hook health-check: invalid JSON from Claude Code: {}",
408	                e
409	            );
410	            println!("{{}}");
411	            return Ok(());
412	        }
413	    };
414	
415	    if !parsed.is_object() {
416	        eprintln!(
417	            "[codeflow] hook health-check: expected JSON object, got {}",
418	            parsed
419	        );
420	        println!("{{}}");
421	        return Ok(());
422	    }
423	
424	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
425	        Some(name) => name,
426	        None => {
427	            println!("{{}}");
428	            return Ok(());
429	        }
430	    };
431	
432	    let tool_input = match parsed.get("tool_input") {
433	        Some(v) if v.is_object() => v,
434	        _ => {
435	            println!("{{}}");
436	            return Ok(());
437	        }
438	    };
439	
440	    // Log to session + dedup check (single connection, best-effort)
441	    let session_id = codeflow_core::util::session_id();
442	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
443	    let session_log = open_session_log(&session_id).ok();
444	
445	    if let Some(ref sl) = session_log {
446	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
447	        if let Ok(row_id) =
448	            sl.record_pre(tool_name, &tool_input_str, file_path.as_deref())
449	        {
450	            sl.write_pre_id(tool_name, file_path.as_deref(), row_id);
451	        }
452	    }
453	
454	    if std::env::var("CODEFLOW_PROVENANCE").as_deref() != Ok("0") {
455	        let _ = capture_provenance(&session_id, tool_name, tool_input);
456	    }
457	
458	    match tool_name {
459	        "Bash" => {
460	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
461	                if should_wrap(command) {
462	                    let codeflow_bin = std::env::current_exe()
463	                        .map(|p| p.to_string_lossy().to_string())
464	                        .unwrap_or_else(|_| "codeflow".to_string());
465	                    let quoted_bin = shell_quote(&codeflow_bin);
466	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
467	                    let response = serde_json::json!({
468	                        "tool_input": {
469	                            "command": rewritten
470	                        }
471	                    });
472	                    println!("{}", serde_json::to_string(&response)?);
473	                    return Ok(());
474	                }
475	            }
476	            println!("{{}}");
477	        }
478	        "Read" | "Grep" | "Glob" => {
479	            if let Some(ref session_log) = session_log {
480	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
481	                    .ok()
482	                    .and_then(|v| v.parse().ok());
483	                let dedup =
484	                    codeflow_core::read_dedup::ReadDedup::new(session_log, window_secs);
485	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
486	
487	                let result = match tool_name {
488	                    "Read" => {
489	                        if let Some(fp) = file_path.as_deref() {
490	                            dedup.check_read(fp)
491	                        } else {
492	                            codeflow_core::read_dedup::ReadDedupResult::Miss
493	                        }
494	                    }
495	                    "Grep" => dedup.check_grep(&tool_input_str),
496	                    "Glob" => dedup.check_glob(&tool_input_str),
497	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
498	                };
499	
500	                match result {
501	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
502	                        context_message,
503	                        tokens_saved,
504	                    } => {
505	                        let response = serde_json::json!({
506	                            "additionalContext": context_message
507	                        });
508	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
509	
510	                        // Track savings
511	                        if tokens_saved > 0 {
512	                            if let Ok(tracking) =
513	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
514	                            {
515	                                let _ = tracking.record(
516	                                    &codeflow_core::tracking::TrackingEvent {
517	                                        command: tool_name.to_string(),
518	                                        input_tokens: tokens_saved,
519	                                        output_tokens: 0,
520	                                        tokens_saved,
521	                                        layer:
522	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
523	                                        project: std::env::current_dir()
524	                                            .unwrap_or_default()
525	                                            .to_string_lossy()
526	                                            .to_string(),
527	                                        session_id: session_id.clone(),
528	                                    },
529	                                );
530	                            }
531	                        }
532	                        return Ok(());
533	                    }
534	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
535	                        println!("{{}}");
536	                    }
537	                }
538	            } else {
539	                println!("{{}}");
540	            }
541	        }
542	        _ => {
543	            println!("{{}}");
544	        }
545	    }
546	
547	    Ok(())
548	}
