550	fn handle_post_tool_use() -> anyhow::Result<()> {
551	    let input = match read_stdin() {
552	        Ok(s) => s,
553	        Err(_) => {
554	            println!("{{}}");
555	            return Ok(());
556	        }
557	    };
558	
559	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
560	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
561	    let tool_result = parsed
562	        .get("tool_result")
563	        .and_then(|v| v.as_str())
564	        .unwrap_or("");
565	
566	    if let Some(tn) = tool_name {
567	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
568	            let file_path = parsed
569	                .get("tool_input")
570	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
571	
572	            let session_id = codeflow_core::util::session_id();
573	            if let Ok(session_log) = open_session_log(&session_id) {
574	                if let Some(row_id) = session_log.take_pre_id(tn, file_path.as_deref()) {
575	                    let capped = if tool_result.len() > 1_048_576 {
576	                        &tool_result[..1_048_576]
577	                    } else {
578	                        tool_result
579	                    };
580	                    let content_hash =
581	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
582	                    let token_count = codeflow_core::util::estimate_tokens(tool_result.len()) as i64;
583	
584	                    let mtime_ns =
585	                        file_path.as_deref().and_then(codeflow_core::util::get_file_mtime_ns);
586	
587	                    let _ = session_log.record_post(
588	                        row_id,
589	                        &content_hash,
590	                        token_count,
591	                        mtime_ns,
592	                    );
593	                }
594	            }
595	        }
596	    }
597	
598	    println!("{{}}");
599	    Ok(())
600	}
