613	fn should_wrap(command: &str) -> bool {
614	    let first_word = command.split_whitespace().next().unwrap_or("");
615	    let stem = std::path::Path::new(first_word)
616	        .file_stem()
617	        .and_then(|s| s.to_str())
618	        .unwrap_or(first_word);
619	    let wrappable = [
620	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
621	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
622	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
623	    ];
624	    wrappable.contains(&stem)
625	}
