627	fn shell_quote(s: &str) -> String {
628	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
629	        format!("'{}'", s.replace('\'', "'\\''"))
630	    } else {
631	        s.to_string()
632	    }
633	}
