64	struct WrapResult {
65	    filter: FilterResult,
66	    dedup_hit: bool,
67	    dedup_summary: Option<String>,
68	}
69	
70	fn compress(
71	    raw_output: &str,
72	    program: &str,
73	    args: &[String],
74	    session_id: &str,
75	    project_dir: &str,
76	) -> Result<WrapResult> {
77	    let data_dir = paths::data_dir();
78	    std::fs::create_dir_all(&data_dir)?;
79	    let db_path = paths::db_path();
80	
81	    let filters_dir = paths::filters_dir();
82	    let pipeline = FilterPipeline::load_from_dir(&filters_dir).unwrap_or_else(|e| {
83	        tracing::debug!("filter load failed, using empty pipeline: {}", e);
84	        FilterPipeline::new()
85	    });
86	
87	    let filter_result = pipeline.apply(program, &args.iter().map(|s| s.to_string()).collect::<Vec<_>>(), raw_output);
88	
89	    let dedup_cache = DedupCache::open(&db_path, session_id)?;
90	    let content_to_check = &filter_result.output;
91	    let fake_mtime = 0u64; // commands dedup on content hash only, mtime irrelevant
92	    let dedup_result = dedup_cache.lookup(
93	        &format!("cmd:{}:{}", program, args.join(" ")),
94	        fake_mtime,
95	        content_to_check,
96	    )?;
97	
98	    let tokens_saved_compress = if filter_result.filter_applied {
99	        codeflow_core::util::estimate_tokens(filter_result.input_len) - codeflow_core::util::estimate_tokens(filter_result.output_len)
100	    } else {
101	        0
102	    };
103	
104	    let tracking = TrackingDb::open(&db_path)?;
105	
106	    if filter_result.filter_applied && tokens_saved_compress > 0 {
107	        tracking.record(&TrackingEvent {
108	            command: program.to_string(),
109	            input_tokens: codeflow_core::util::estimate_tokens(filter_result.input_len) as u64,
110	            output_tokens: codeflow_core::util::estimate_tokens(filter_result.output_len) as u64,
111	            tokens_saved: tokens_saved_compress as u64,
112	            layer: SavingsLayer::Compression,
113	            project: project_dir.to_string(),
114	            session_id: session_id.to_string(),
115	        })?;
116	    }
117	
118	    if dedup_result.cache_hit {
119	        tracking.record(&TrackingEvent {
120	            command: program.to_string(),
121	            input_tokens: codeflow_core::util::estimate_tokens(filter_result.output_len) as u64,
122	            output_tokens: 0,
123	            tokens_saved: dedup_result.tokens_saved,
124	            layer: SavingsLayer::Dedup,
125	            project: project_dir.to_string(),
126	            session_id: session_id.to_string(),
127	        })?;
128	    }
129	
130	    if let Ok(event_buf) = EventBuffer::open(&db_path) {
131	        let event = proto::Event {
132	            id: uuid::Uuid::new_v4().to_string(),
133	            timestamp_ms: chrono::Utc::now().timestamp_millis(),
134	            session_id: session_id.to_string(),
135	            project_dir: project_dir.to_string(),
136	            command: format!("{} {}", program, args.join(" ")),
137	            event_type: if dedup_result.cache_hit && dedup_result.tokens_saved > tokens_saved_compress as u64 {
138	                proto::EventType::Dedup as i32
139	            } else if filter_result.filter_applied {
140	                proto::EventType::Compression as i32
141	            } else {
142	                proto::EventType::Unspecified as i32
143	            },
144	            compression: Some(proto::CompressionEvent {
145	                input_bytes: filter_result.input_len as u64,
146	                output_bytes: filter_result.output_len as u64,
147	                input_tokens: codeflow_core::util::estimate_tokens(filter_result.input_len) as u64,
148	                output_tokens: codeflow_core::util::estimate_tokens(filter_result.output_len) as u64,
149	                tokens_saved: tokens_saved_compress as u64,
150	                filter_name: program.to_string(),
151	                compression_level: "default".to_string(),
152	                latency_ms: 0.0,
153	            }),
154	            dedup: if dedup_result.cache_hit {
155	                Some(proto::DedupEvent {
156	                    content_hash: dedup_result.content_hash.clone(),
157	                    cache_hit: true,
158	                    tokens_saved: dedup_result.tokens_saved,
159	                    file_path: String::new(),
160	                    latency_ms: 0.0,
161	                })
162	            } else {
163	                None
164	            },
165	            provenance: None,
166	            cost: None,
167	            governance: None,
168	            quality: None,
169	        };
170	        let _ = event_buf.append(&event);
171	    }
172	
173	    Ok(WrapResult {
174	        filter: filter_result,
175	        dedup_hit: dedup_result.cache_hit,
176	        dedup_summary: dedup_result.summary,
177	    })
178	}
