180	struct CommandOutput {
181	    combined: String,
182	    exit_code: Option<i32>,
183	}
184	
185	fn run_command(program: &str, args: &[String]) -> Result<CommandOutput> {
186	    let output = Command::new(program)
187	        .args(args)
188	        .output()
189	        .map_err(|e| anyhow::anyhow!("failed to execute {}: {}", program, e))?;
190	
191	    let mut combined = String::new();
192	    if !output.stdout.is_empty() {
193	        combined.push_str(&String::from_utf8_lossy(&output.stdout));
194	    }
195	    if !output.stderr.is_empty() {
196	        if !combined.is_empty() {
197	            combined.push('\n');
198	        }
199	        combined.push_str(&String::from_utf8_lossy(&output.stderr));
200	    }
201	    Ok(CommandOutput {
202	        combined,
203	        exit_code: output.status.code(),
204	    })
205	}
206	
207	fn print_output(text: &str) {
208	    let stdout = std::io::stdout();
209	    let mut handle = stdout.lock();
210	    let _ = handle.write_all(text.as_bytes());
211	    if !text.ends_with('\n') {
212	        let _ = handle.write_all(b"\n");
213	    }
214	    let _ = handle.flush();
215	}
216	
217	fn propagate_exit(exit_code: Option<i32>) {
218	    if let Some(code) = exit_code {
219	        if code != 0 {
220	            std::process::exit(code);
221	        }
222	    }
223	}
