1	use anyhow::Result;
2	use codeflow_core::events::EventBuffer;
3	use codeflow_core::proto;
4	use flate2::write::GzEncoder;
5	use flate2::Compression;
6	use prost::Message;
7	use std::io::Write;
8	use std::time::{Duration, Instant};
9	
10	use crate::paths;
11	
12	const BATCH_MAX_EVENTS: usize = 50;
13	const BATCH_MAX_BYTES: usize = 512 * 1024;
14	const BATCH_FLUSH_INTERVAL: Duration = Duration::from_secs(30);
15	const MAX_RETRIES: u32 = 8;
16	const CIRCUIT_BREAKER_THRESHOLD: u32 = 5;
17	const CIRCUIT_BREAKER_COOLDOWN: Duration = Duration::from_secs(600);
18	
19	pub struct SyncConfig {
20	    pub api_url: String,
21	    pub api_key: Option<String>,
22	    pub one_shot: bool,
23	}
24	
25	impl Default for SyncConfig {
26	    fn default() -> Self {
27	        Self {
28	            api_url: std::env::var("CODEFLOW_API_URL")
29	                .unwrap_or_else(|_| "http://localhost:8080".to_string()),
30	            api_key: std::env::var("CODEFLOW_API_KEY").ok(),
31	            one_shot: false,
32	        }
33	    }
34	}
35	
36	pub fn run(config: SyncConfig) -> Result<()> {
37	    let db_path = paths::db_path();
38	    if !db_path.exists() {
39	        println!("No events to sync.");
40	        return Ok(());
41	    }
42	
43	    let event_buf = EventBuffer::open(&db_path)?;
44	    let pending = event_buf.pending_count()?;
45	    println!("Pending events: {}", pending);
46	
47	    if pending == 0 {
48	        println!("Nothing to sync.");
49	        return Ok(());
50	    }
51	
52	    let mut circuit_failures: u32 = 0;
53	    let mut circuit_open_until: Option<Instant> = None;
54	
55	    loop {
56	        if let Some(open_until) = circuit_open_until {
57	            if Instant::now() < open_until {
58	                if config.one_shot {
59	                    eprintln!("Circuit breaker open. Retry later.");
60	                    return Ok(());
61	                }
62	                let remaining = open_until - Instant::now();
63	                tracing::warn!(secs = remaining.as_secs(), "circuit breaker open, waiting");
64	                std::thread::sleep(remaining.min(Duration::from_secs(10)));
65	                continue;
66	            }
67	            circuit_open_until = None;
68	            circuit_failures = 0;
69	        }
70	
71	        let batch = event_buf.consume_batch(BATCH_MAX_EVENTS)?;
72	        if batch.is_empty() {
73	            if config.one_shot {
74	                println!("All events synced.");
75	                return Ok(());
76	            }
77	            std::thread::sleep(BATCH_FLUSH_INTERVAL);
78	            continue;
79	        }
80	
81	        let ids: Vec<i64> = batch.iter().map(|(id, _)| *id).collect();
82	        let events: Vec<proto::Event> = batch.into_iter().map(|(_, e)| e).collect();
83	
84	        let payload = encode_batch(&events, &config)?;
85	
86	        if payload.len() > BATCH_MAX_BYTES {
87	            tracing::warn!(
88	                size = payload.len(),
89	                "batch exceeds max bytes, splitting not implemented — sending anyway"
90	            );
91	        }
92	
93	        match send_batch(&config, &payload) {
94	            Ok(()) => {
95	                event_buf.mark_consumed(&ids)?;
96	                event_buf.purge_consumed()?;
97	                circuit_failures = 0;
98	                tracing::info!(count = ids.len(), "batch synced");
99	                println!("  Synced {} events", ids.len());
100	            }
101	            Err(e) => {
102	                circuit_failures += 1;
103	                tracing::error!(err = %e, failures = circuit_failures, "sync failed");
104	                eprintln!("  Sync failed: {} (attempt {}/{})", e, circuit_failures, CIRCUIT_BREAKER_THRESHOLD);
105	
106	                if circuit_failures >= CIRCUIT_BREAKER_THRESHOLD {
107	                    circuit_open_until = Some(Instant::now() + CIRCUIT_BREAKER_COOLDOWN);
108	                    tracing::warn!("circuit breaker opened");
109	                    eprintln!("  Circuit breaker opened — will retry in {}s", CIRCUIT_BREAKER_COOLDOWN.as_secs());
110	                }
111	
112	                if config.one_shot {
113	                    return Err(e);
114	                }
115	
116	                let backoff = Duration::from_secs(2u64.pow(circuit_failures.min(MAX_RETRIES)));
117	                std::thread::sleep(backoff);
118	            }
119	        }
120	    }
121	}
122	
123	fn encode_batch(events: &[proto::Event], config: &SyncConfig) -> Result<Vec<u8>> {
124	    let batch = proto::EventBatch {
125	        cli_version: env!("CARGO_PKG_VERSION").to_string(),
126	        machine_id: machine_id(),
127	        events: events.to_vec(),
128	    };
129	
130	    let mut proto_buf = Vec::with_capacity(batch.encoded_len());
131	    batch.encode(&mut proto_buf)?;
132	
133	    let mut encoder = GzEncoder::new(Vec::new(), Compression::fast());
134	    encoder.write_all(&proto_buf)?;
135	    let compressed = encoder.finish()?;
136	
137	    tracing::debug!(
138	        proto_size = proto_buf.len(),
139	        gzip_size = compressed.len(),
140	        ratio = format!("{:.1}%", (1.0 - compressed.len() as f64 / proto_buf.len() as f64) * 100.0),
141	        "batch encoded"
142	    );
143	
144	    let _ = config; // config used for future auth headers
145	    Ok(compressed)
146	}
147	
148	fn send_batch(config: &SyncConfig, payload: &[u8]) -> Result<()> {
149	    let url = format!("{}/v1/events", config.api_url);
150	
151	    let mut req = ureq::post(&url)
152	        .header("Content-Type", "application/x-protobuf")
153	        .header("Content-Encoding", "gzip");
154	
155	    if let Some(key) = &config.api_key {
156	        req = req.header("Authorization", &format!("Bearer {}", key));
157	    }
158	
159	    let mut resp = req.send(payload)
160	        .map_err(|e| anyhow::anyhow!("ingest API request failed: {}", e))?;
161	
162	    let status = resp.status().as_u16();
163	    if status >= 400 {
164	        let body = resp.body_mut().read_to_string()
165	            .unwrap_or_default();
166	        anyhow::bail!("ingest API returned {}: {}", status, body);
167	    }
168	
169	    Ok(())
170	}
171	
172	fn machine_id() -> String {
173	    std::env::var("CODEFLOW_MACHINE_ID").unwrap_or_else(|_| {
174	        let hostname = hostname::get()
175	            .map(|h| h.to_string_lossy().to_string())
176	            .unwrap_or_else(|_| "unknown".to_string());
177	        let hash = blake3::hash(hostname.as_bytes());
178	        hash.to_hex()[..16].to_string()
179	    })
180	}
